/**
 * Map island. Phase 2.3a: the terrain preview (generated by `pnpm tiles`) with landmark links placed by
 * normalised coordinates. Rendered on the server only (no client directive), so it ships no map JS yet.
 * Phase 2.3c hydrates it and swaps the <img> for OpenSeadragon deep-zoom tiles, keeping the landmark overlay.
 * Hidden below 768 px by CSS; mobile visitors use the quest log instead.
 */
import './map.css';

export interface Landmark {
  id: string;
  name: string;
  /** Short description used in the accessible name, e.g. the project title. */
  label: string;
  href: string;
  /** Normalised 0–1 position on the map image. */
  x: number;
  y: number;
}

interface Props {
  landmarks: Landmark[];
  /** Full render size in px (from terrain.dzi); sets the frame's aspect ratio so landmarks land on the right pixels. */
  width: number;
  height: number;
}

export default function MapIsland({ landmarks, width, height }: Props) {
  return (
    <div class="map-frame" style={{ aspectRatio: `${width} / ${height}` }}>
      <img src="/map/preview.webp" alt="" width={width} height={height} loading="lazy" decoding="async" />
      <ul class="map-landmarks">
        {landmarks.map((l) => (
          <li key={l.id} style={{ left: `${l.x * 100}%`, top: `${l.y * 100}%` }}>
            <a href={l.href} aria-label={`${l.name}: ${l.label}`}>
              {l.name}
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}
